 92	{
 93	    public static void WriteSelectedColumns(string path, IReadOnlyList<string> selectedColumns, Stream output)
 94	    {
 95	        using var reader = new StreamReader(File.OpenRead(path));
 96	        using var writer = new StreamWriter(output, leaveOpen: true)
 97	        {
 98	            NewLine = Environment.NewLine
 99	        };
100	
101	        var headerLine = reader.ReadLine() ?? throw new InvalidOperationException("CSV file is empty");
102	        var headers = ParseCsvLine(headerLine);
103	        var headerIndexes = headers
104	            .Select((header, index) => new { header, index })
105	            .ToDictionary(x => x.header, x => x.index, StringComparer.Ordinal);
106	
107	        var selectedIndexes = selectedColumns
108	            .Select(columnName => headerIndexes.TryGetValue(columnName, out var index)
109	                ? index
110	                : throw new InvalidOperationException($"Column not found: {columnName}"))
111	            .ToArray();
112	
113	        writer.WriteLine(string.Join(",", selectedColumns));
114	
115	        string? line;
116	        while ((line = reader.ReadLine()) is not null)
117	        {
118	            if (line.Length == 0)
119	            {
120	                writer.WriteLine();
121	                continue;
122	            }
123	
124	            var values = ParseCsvLine(line);
125	            var projectedValues = selectedIndexes.Select(index => index < values.Count ? values[index] : string.Empty);
126	            writer.WriteLine(string.Join(",", projectedValues));
127	        }
128	
129	        writer.Flush();
130	    }
