245	    public static void WriteHeadRows(string path, int rowCount, Stream output)
246	    {
247	        if (rowCount <= 0)
248	        {
249	            throw new InvalidOperationException("Row count must be a positive integer");
250	        }
251	
252	        using var reader = new StreamReader(File.OpenRead(path));
253	        using var writer = new StreamWriter(output, leaveOpen: true)
254	        {
255	            NewLine = Environment.NewLine
256	        };
257	
258	        var headerLine = reader.ReadLine() ?? throw new InvalidOperationException("CSV file is empty");
259	        writer.WriteLine(headerLine);
260	
261	        var writtenRows = 0;
262	        string? line;
263	        while ((line = reader.ReadLine()) is not null && writtenRows < rowCount)
264	        {
265	            if (line.Length == 0)
266	            {
267	                continue;
268	            }
269	
270	            writer.WriteLine(line);
271	            writtenRows++;
272	        }
273	
274	        writer.Flush();
275	    }
