285	        {
286	            return op switch
287	            {
288	                ComparisonOperator.Equal => leftNumber == rightNumber,
289	                ComparisonOperator.NotEqual => leftNumber != rightNumber,
290	                ComparisonOperator.GreaterThan => leftNumber > rightNumber,
